//=========================================================================
// mesh_top : 4x4 axi noc mesh, generated by sw.lisp --aximesh
//   do not edit : config is the *aximesh* list in sw.lisp
//   node id = y*4+x ; ROM@0 IO@1 UART0@2 RAM@3 ; 12 cpus
//
module mesh_top
(  output [63:0] io_i, io_oe, io_ie,
  input  [63:0] io_o,
  output        halt,
  output [ 7:0] debug,
  input         uart0_rx,
  output        uart0_tx,
  input         ioclk,
  input         rstb,
  input         clk
);

localparam NN = 16; // mesh nodes
localparam NC = 12; // cpus

// one-way axi link bundles : eb/wb/sb/nb[n] = traffic leaving node
// n to the east/west/south/north, slot 16 = off-mesh dummy.
// l2r[n] = local masters -> router L slave ; r2l[n] = router L -> local slave
wire [544:0] eb_awaddr, eb_wdata, eb_araddr, eb_rdata;
wire [68:0] eb_wstrb;
wire [51:0] eb_arprot;
wire [34:0] eb_bresp, eb_rresp;
wire [16:0] eb_awvalid, eb_awready, eb_wvalid, eb_wready;
wire [16:0] eb_bvalid, eb_bready, eb_arvalid, eb_arready, eb_rvalid, eb_rready;
wire [544:0] wb_awaddr, wb_wdata, wb_araddr, wb_rdata;
wire [68:0] wb_wstrb;
wire [51:0] wb_arprot;
wire [34:0] wb_bresp, wb_rresp;
wire [16:0] wb_awvalid, wb_awready, wb_wvalid, wb_wready;
wire [16:0] wb_bvalid, wb_bready, wb_arvalid, wb_arready, wb_rvalid, wb_rready;
wire [544:0] sb_awaddr, sb_wdata, sb_araddr, sb_rdata;
wire [68:0] sb_wstrb;
wire [51:0] sb_arprot;
wire [34:0] sb_bresp, sb_rresp;
wire [16:0] sb_awvalid, sb_awready, sb_wvalid, sb_wready;
wire [16:0] sb_bvalid, sb_bready, sb_arvalid, sb_arready, sb_rvalid, sb_rready;
wire [544:0] nb_awaddr, nb_wdata, nb_araddr, nb_rdata;
wire [68:0] nb_wstrb;
wire [51:0] nb_arprot;
wire [34:0] nb_bresp, nb_rresp;
wire [16:0] nb_awvalid, nb_awready, nb_wvalid, nb_wready;
wire [16:0] nb_bvalid, nb_bready, nb_arvalid, nb_arready, nb_rvalid, nb_rready;

wire [512:0] l2r_awaddr, l2r_wdata, l2r_araddr, l2r_rdata;
wire [64:0] l2r_wstrb;
wire [48:0] l2r_arprot;
wire [32:0] l2r_bresp, l2r_rresp;
wire [15:0] l2r_awvalid, l2r_awready, l2r_wvalid, l2r_wready;
wire [15:0] l2r_bvalid, l2r_bready, l2r_arvalid, l2r_arready, l2r_rvalid, l2r_rready;
