// cpu-side buses (before the local mux) : im read only, dm full
wire [384:0] ci_araddr, ci_rdata;
wire [36:0] ci_arprot;
wire [24:0] ci_rresp;
wire [11:0] ci_arvalid, ci_arready, ci_rvalid, ci_rready;
