wire [11:0] haltv;
assign halt = haltv[0];

// dummy slot 16 : off-mesh boundary ports see an idle link
assign eb_awaddr[16*32 +: 32] = 32'd0; assign eb_awvalid[16] = 1'b0;
assign eb_wdata[16*32 +: 32] = 32'd0; assign eb_wstrb[16*4 +: 4] = 4'd0; assign eb_wvalid[16] = 1'b0; assign eb_bready[16] = 1'b0;
